fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(2, 12345);
        host::display::state_set(3, w / 2);
        host::display::state_set(4, h / 2);
    }
    let seed: i32 = host::display::state_get(2) * 1103515245 + 12345;
    host::display::state_set(2, seed);
    let mut dir: i32 = (seed >> 16) & 3;
    let mut x: i32 = host::display::state_get(3);
    let mut y: i32 = host::display::state_get(4);
    if dir == 0 { x = x + 4; }
    if dir == 1 { x = x - 4; }
    if dir == 2 { y = y + 4; }
    if dir == 3 { y = y - 4; }
    if x < 4 { x = 4; }
    if x > w - 4 { x = w - 4; }
    if y < 4 { y = 4; }
    if y > h - 4 { y = h - 4; }
    host::display::state_set(3, x);
    host::display::state_set(4, y);
    let head: i32 = host::display::state_get(1);
    host::display::state_set(16 + head * 2, x);
    host::display::state_set(17 + head * 2, y);
    host::display::state_set(1, (head + 1) % 16);
    host::display::clear(0x000000);
    let mut i: i32 = 0;
    while i < 16 {
        let tx: i32 = host::display::state_get(16 + i * 2);
        let ty: i32 = host::display::state_get(17 + i * 2);
        host::display::fill_rect(tx - 1, ty - 1, 2, 2, 0x204020);
        i = i + 1;
    }
    host::display::fill_rect(x - 3, y - 3, 6, 6, 0xc0ff40);
    host::display::present();
}
